const source=$('Generate 26 Unified Channel QA Events').first()?.json||{};
if(source.contract!=='T404_V172_UNIFIED_QA_BATCH_V1'||source.input_trust!=='MANUAL_SYNTHETIC_FIXTURE_ONLY'||!Array.isArray(source.cases)||source.cases.length!==26)throw Error('QA_INPUT_CONTRACT_DENIED');
const rows=$input.all().map(i=>i.json||{});
if(rows.length!==7)throw Error('PERSISTED_QA_BINDING_COUNT_MISMATCH');
const keys=new Set(),profiles=new Map();
for(const r of rows){
 const k=r.channel+'|'+r.installation_ref;
 if(keys.has(k))throw Error('DUPLICATED_CHANNEL_INSTALLATION');
 keys.add(k);
 if(r.approval_scope!=='SYNTHETIC_ONLY'||r.owner_authority_verified!==false||r.read_only!==true)
  throw Error('NON_QA_OWNERSHIP_FLAG_DENIED');
 if(!/^QA_TENANT_[12]$/.test(String(r.tenant_ref))||
 !/^QA_STORE_[ABC]$/.test(String(r.store_ref))||
 !/^QA_BOT_[ABC]$/.test(String(r.bot_ref))||
 r.bot_version!==r.bot_ref+'_V1'||
 r.prompt_version!=='QA_PROMPT_'+r.store_ref.slice(-1)+'_V1'||
 r.knowledge_version!=='QA_KNOWLEDGE_'+r.store_ref.slice(-1)+'_V1'||
 r.policy_version!=='QA_POLICY_V172')throw Error('INVALID_QA_PROFILE_VERSION');
 const expectedTenant=r.store_ref==='QA_STORE_C'?'QA_TENANT_2':'QA_TENANT_1';
 if(r.tenant_ref!==expectedTenant||r.bot_ref!=='QA_BOT_'+r.store_ref.slice(-1))
  throw Error('QA_CROSS_STORE_PROFILE_CONFLICT');
 const profile=[r.store_ref,r.bot_ref,r.bot_version,r.prompt_version,r.knowledge_version,r.policy_version,
 r.tone,r.selling_mode,r.tool_allowlist,r.subscription_active,r.store_paused,r.price_vnd,r.stock,r.product_label].join('|');
 if(profiles.has(r.store_ref)&&profiles.get(r.store_ref)!==profile)throw Error('QA_SAME_STORE_PROFILE_DRIFT_ACROSS_CHANNELS');
 profiles.set(r.store_ref,profile);
}
const validFields=new Set(['case_id','expected','event_id','channel','installation_ref','customer_ref','message_type','text','requested_tool']);
const allowedChannels=new Set(['messenger','zalo_bot','zalo_oa','website']);
const seen=new Map(),results=[];
for(const c of source.cases){
 let status='DENY',reason='INVALID_INPUT',trustStore=null,trustBot=null,tenant=null,price=null,stock=null,botVersion=null;
 try{
  if(Object.keys(c).some(k=>!validFields.has(k)))throw Error('CLIENT_SCOPE_OR_IDENTITY_SPOOF');
  if(typeof c.event_id!=='string'||!/^QA_EVENT_[0-9]{2}$/.test(c.event_id)||
    !allowedChannels.has(c.channel)||typeof c.installation_ref!=='string'||!/^QA_/.test(c.installation_ref)||
    typeof c.customer_ref!=='string'||!/^QA_CUSTOMER_[0-9]{3}$/.test(c.customer_ref))
   throw Error('UNTRUSTED_CHANNEL_EVENT');
  if(c.message_type!=='text'||typeof c.text!=='string'||c.text.length<1||c.text.length>500)
   throw Error('UNSUPPORTED_OR_OVERSIZED_MESSAGE');
  if(typeof c.requested_tool!=='string')throw Error('INVALID_TOOL');
  const k=c.channel+'|'+c.installation_ref;
  const matches=rows.filter(r=>r.channel+'|'+r.installation_ref===k);
  if(matches.length!==1)throw Error('UNBOUND_INSTALLATION');
  const r=matches[0];
  if(r.status!=='QA_APPROVED'||r.subscription_active!==true||r.store_paused!==false)
   throw Error('BOT_REVOKED_SUSPENDED_OR_PAUSED');
  if(r.tool_allowlist!=='catalog_read'||c.requested_tool!=='catalog_read')
   throw Error('UNAUTHORIZED_WRITE_OR_ORDER_LOOKUP');
  const dedupKey=[c.channel,c.installation_ref,c.event_id].join('|');
  const fingerprint=[c.channel,c.installation_ref,c.event_id,c.customer_ref,c.message_type,c.text,c.requested_tool].join('|');
  if(seen.has(dedupKey)){
   if(seen.get(dedupKey)!==fingerprint)throw Error('CONFLICTING_EVENT_REPLAY');
   status='DUPLICATE';reason='IN_MEMORY_QA_REPLAY_ONLY';
  }else{
   seen.set(dedupKey,fingerprint);status='ALLOW';reason='PERSISTED_QA_PROFILE_READ_ONLY';
   trustStore=r.store_ref;trustBot=r.bot_ref;tenant=r.tenant_ref;botVersion=r.bot_version;
   price=r.price_vnd;stock=r.stock;
  }
 }catch(err){status='DENY';reason=String(err.message||'DENIED').slice(0,72);}
 results.push({case_id:c.case_id,expected:c.expected,status,reason,channel:c.channel,
  tenant:tenant,store:trustStore,bot:trustBot,bot_version:botVersion,price_vnd:price,stock,
  provider_verified:false,hosted_rls_verified:false,customer_cross_channel_link_verified:false,
  outbound:'MOCK_ONLY_NOT_SENT',model_calls:0,provider_sends:0,commerce_writes:0});
}
return [{json:{contract:source.contract,source_mode:source.input_trust,bindings:rows.length,results}}];

const x=$input.first()?.json||{};const cases=x.results||[];
if(x.contract!=='T404_V172_UNIFIED_QA_BATCH_V1'||x.source_mode!=='MANUAL_SYNTHETIC_FIXTURE_ONLY'||
 cases.length!==26||x.bindings!==7||new Set(cases.map(c=>c.case_id)).size!==26)throw Error('INVALID_QA_CORE_RESULT');
for(const c of cases){
 if(c.status!==c.expected)throw Error('P0_CASE_EXPECTATION_FAILED_'+c.case_id+'_'+c.status);
 if(c.model_calls!==0||c.provider_sends!==0||c.commerce_writes!==0||
 c.provider_verified!==false||c.hosted_rls_verified!==false||
 c.customer_cross_channel_link_verified!==false||c.outbound!=='MOCK_ONLY_NOT_SENT')
   throw Error('UNAUTHORIZED_PROVIDER_OR_HOSTED_ACTION');
 if(c.status==='ALLOW'&&(!/^QA_TENANT_[12]$/.test(c.tenant)||!/^QA_STORE_[ABC]$/.test(c.store)||
 !/^QA_BOT_[ABC]$/.test(c.bot)||!Number.isSafeInteger(c.price_vnd)||c.price_vnd<=0))
  throw Error('INVALID_ALLOW_CONTEXT');
 if(c.status==='DENY'&&(c.store!==null||c.bot!==null))throw Error('DENIED_CASE_HAS_TRUSTED_CONTEXT');
}
const allow=cases.filter(c=>c.status==='ALLOW'),denied=cases.filter(c=>c.status==='DENY'),dups=cases.filter(c=>c.status==='DUPLICATE');
if(allow.length!==6||denied.length!==19||dups.length!==1)throw Error('CASE_DISTRIBUTION_MISMATCH');
const a=allow.find(c=>c.case_id==='QA_V172_01'),b=allow.find(c=>c.case_id==='QA_V172_02'),
 z=allow.find(c=>c.case_id==='QA_V172_04'),w=allow.find(c=>c.case_id==='QA_V172_05'),other=allow.find(c=>c.case_id==='QA_V172_06');
if(a?.store!=='QA_STORE_A'||a?.price_vnd!==159000||b?.store!=='QA_STORE_B'||b?.price_vnd!==259000||
 a?.tenant!==b?.tenant||z?.store!=='QA_STORE_B'||w?.store!=='QA_STORE_A'||
 other?.tenant===a?.tenant)throw Error('SAME_TENANT_STORE_OR_CHANNEL_SCOPE_FAILED');
return [{json:{
 status:'V172_UNIFIED_CHANNEL_STORE_BOT_QA_PASS',total:cases.length,passed:cases.length,
 allow:allow.length,deny:denied.length,duplicate:dups.length,channels_supported_in_qa:4,
 same_tenant_cross_store_enforced:true,isolated_different_tenant:true,
 customer_cross_channel_identity_verified:false,provider_webhooks_verified:false,
 hosted_rls_verified:false,installed_channels_verified:false,
 actual_messenger_zalo_website_ingress:false,model_calls:0,
 provider_sends:0,commerce_writes:0,outbound:'MOCK_ONLY_NOT_SENT',
 cases:cases.map(c=>({id:c.case_id,status:c.status,reason:c.reason,channel:c.channel,
  store:c.store,bot:c.bot,price_vnd:c.price_vnd}))
 }}];
